'use client';
import { useEffect, useRef, useState } from 'react';
import { cx } from '../lib/cx';
import { useReducedMotion, useSeconds } from '../lib/hooks';
import { Swap } from '../lib/motion';
import '../designme.css';
import './thinking-states.css';

export type ThinkingVariant = 'orbit' | 'morph' | 'scan' | 'stream' | 'matrix' | 'stack';

export interface ThinkingStatesProps {
  /** Which indicator: dots circling a core, a shape that morphs, a line scanning skeleton text, tokens with a typed line,
      a twinkling dot grid or shuffling pages */
  variant?: ThinkingVariant;
  /** The status lines, like "Reading 3 files". With more than one, they take turns every `interval` unless `current` is set */
  steps?: string[];
  /** Index of the line to show. Leave it out to let the lines take turns by themselves */
  current?: number;
  /** Milliseconds each line shows for when they take turns by themselves */
  interval?: number;
  /** Seconds shown at the end of the line. Counts by itself when left out; false hides it */
  seconds?: number | false;
  className?: string;
}

type GridKind = 'orbit' | 'morph' | 'scan' | 'stream';
/* Orbit, Morph, Scan and Stream are drawn on a grid of dots, each at its own density (Orbit 5 by 5, Scan 6 by 6, Morph 7 by 7,
   Stream 4 by 3, the size of Matrix): which part each dot plays, and its place in the run as an animation delay */
const grid = (k: GridKind) => {
  const n = { orbit: 5, scan: 6, morph: 7, stream: 4 }[k], rows = k === 'stream' ? 3 : n, at = (x: number, y: number) => y * n + x;
  const cls: string[] = Array(n * rows).fill(''), dly: (number | null)[] = Array(n * rows).fill(null), pose = new Set<number>();
  const run = (order: number[], dur: number) => order.forEach((c, i) => { dly[c] = (i / order.length - 1) * dur; });
  if (k === 'orbit') {
    const ring: number[] = [];
    for (let x = 0; x < n; x++) ring.push(at(x, 0));
    for (let y = 1; y < n; y++) ring.push(at(n - 1, y));
    for (let x = n - 2; x >= 0; x--) ring.push(at(x, n - 1));
    for (let y = n - 2; y > 0; y--) ring.push(at(0, y));
    ring.forEach(c => { cls[c] = 'r'; }); run(ring, 1.6); cls[at(2, 2)] = 'c';
    [0, ring.length - 1, ring.length - 2].forEach(i => pose.add(ring[i]));
  } else if (k === 'scan') {
    const len = [6, 0, 5, 0, 3, 0];
    for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) { const c = at(x, y); cls[c] = x < len[y] ? 'l' : 'b'; dly[c] = (x / n - 1) * 1.6; if (x === 2) pose.add(c); }
  } else if (k === 'morph') {
    for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
      const rect = y >= 1 && y <= 5, circ = (x - 3) ** 2 + (y - 3) ** 2 <= 10, tri = Math.abs(x - 3) <= y / 2;
      const c = at(x, y); cls[c] = 'm' + ((rect ? 1 : 0) | (circ ? 2 : 0) | (tri ? 4 : 0)); if (circ) pose.add(c);
      dly[c] = -(((c * 37 + 11) % 17) / 17) * .32;
    }
  } else {
    for (let y = 0; y < rows; y++) for (let x = 0; x < n; x++) { const c = at(x, y); cls[c] = 's' + c; if (y < 2) pose.add(c); }
  }
  return cls.map((x, c) => ({ cls: [x, pose.has(c) && 'p'].filter(Boolean).map(y => 'dm-' + y).join(' '), delay: dly[c] }));
};
const GRIDS = { orbit: grid('orbit'), morph: grid('morph'), scan: grid('scan'), stream: grid('stream') };
const Dots = ({ k }: { k: GridKind }) => (
  <span className="dm-ths-dg" data-k={k}>{GRIDS[k].map((d, i) => <i key={i} className={d.cls} style={d.delay != null ? { animationDelay: d.delay.toFixed(3) + 's' } : undefined} />)}</span>
);

const Mark = ({ variant }: { variant: ThinkingVariant }) => {
  switch (variant) {
    case 'morph': case 'scan': case 'stream': return <Dots k={variant} />;
    case 'matrix': return <span className="dm-ths-mtx">{Array.from({ length: 16 }, (_, i) => <i key={i} />)}</span>;
    case 'stack': return <span className="dm-ths-stk"><i /><i /><i /></span>;
    default: return <Dots k="orbit" />;
  }
};

/** Six thinking indicators to pick from, each a small mark beside a status line that steps through what the agent is doing. */
export function ThinkingStates({ variant = 'orbit', steps = ['Thinking'], current, interval = 2600, seconds, className }: ThinkingStatesProps) {
  const reduce = useReducedMotion();
  const [auto, setAuto] = useState(0);
  useEffect(() => {
    if (current !== undefined || steps.length < 2) return;
    const id = setInterval(() => setAuto(i => (i + 1) % steps.length), interval);
    return () => clearInterval(id);
  }, [current, steps.length, interval]);
  const text = steps[Math.max(0, Math.min(current ?? auto, steps.length - 1))] ?? '';
  const counted = useSeconds(seconds === undefined);
  const secs = seconds === false ? null : seconds ?? counted;
  // Stream types each new line out behind its caret; switching to Stream mid-line shows the line whole
  const stream = variant === 'stream';
  const [typed, setTyped] = useState(text.length);
  const last = useRef(text);
  useEffect(() => {
    const fresh = last.current !== text; last.current = text;
    if (!stream || reduce || !fresh) { setTyped(text.length); return; }
    let n = 0; setTyped(0);
    const id = setInterval(() => { n++; setTyped(n); if (n >= text.length) clearInterval(id); }, 32);
    return () => clearInterval(id);
  }, [text, stream, reduce]);
  return (
    <div data-dm="" data-v={variant} className={cx('dm-ths', className)}>
      <div className="dm-ths-row">
        <span className="dm-ths-mk" aria-hidden="true"><Mark variant={variant} /></span>
        <span className="dm-ths-l" aria-hidden="true">
          {stream ? <span className="dm-ths-tx">{text.slice(0, typed)}</span> : <Swap className={cx('dm-ths-tx', variant === 'orbit' && 'dm-shim')}>{text}</Swap>}
          {stream && <span className="dm-ths-car" />}
        </span>
        {secs !== null && <span className="dm-ths-t dm-num" aria-hidden="true">{secs}s</span>}
      </div>
      {/* a screen reader hears each new line once, never the letters as they type */}
      <span className="dm-ths-sr" role="status" aria-live="polite">{text}</span>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Thinking states ---------- */
/* six ways to show that the agent is thinking, to pick from: each is a small mark on a tile beside one status line that
   steps through what the agent is doing, and a screen reader hears each step once (the polite status), never each frame.
   Orbit, Morph, Scan and Stream are dot grids like Matrix, each at its own density (owner, 5 Nov). Orbit: a light round the edge,
   the line shimmering. Morph: a rectangle, a circle, a triangle. Scan: a column sweeping lines of dots. Stream: three lines of dots
   filling one by one, then fading, the line typed out behind a caret. Matrix: a grid
   of dots lighting up at random. Stack: pages shuffling to the front. Marks are the accent and everything else is grey;
   with reduced motion every mark holds still in a legible pose and only the line changes */
.dm-ths{width:100%;max-width:264px;margin-inline:auto;min-height:84px;display:flex;flex-direction:column;justify-content:center;gap:var(--dm-s-3);position:relative}
.dm-ths-row{display:flex;align-items:center;gap:10px;min-width:0}
.dm-ths-mk{position:relative;width:28px;height:28px;flex:none;display:grid;place-items:center;border-radius:calc(9px * var(--dm-rk));background:var(--dm-chip);color:var(--dm-accent-mark,var(--dm-accent))}
.dm-ths-l{flex:0 1 auto;min-width:0;font-size:14px;line-height:20px;color:var(--dm-fg);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-ths-car{display:inline-block;width:2px;height:15px;margin-left:2px;vertical-align:-3px;border-radius:1px;background:var(--dm-accent-mark,var(--dm-accent));animation:dm-thsblink 1s steps(1,end) infinite}
@keyframes dm-thsblink{50%{opacity:0}}
.dm-ths-t{flex:none;font-size:13px;color:var(--dm-muted)}
.dm-ths-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
/* Orbit, Morph, Scan and Stream are drawn on a grid of dots like Matrix, each at its own density (owner, 5 Nov):
   Orbit 5 by 5, Scan 6 by 6, Morph 7 by 7 and Stream 4 by 3. The grid (.ths-dg) is written by thsGrid(); each dot's part
   in the pattern is a class, and its place in the run an inline animation-delay */
.dm-ths-dg{display:grid;grid-template-columns:repeat(var(--dm-n),var(--dm-ds));gap:var(--dm-dg);--dm-ds:2px;--dm-dg:1px}
.dm-ths-dg i{display:block;width:var(--dm-ds);height:var(--dm-ds);border-radius:50%;background:currentColor;opacity:.14}
/* Orbit: a light runs round the ring with a fading tail, the dot in the middle breathing */
.dm-ths-dg[data-k="orbit"]{--dm-n:5;--dm-ds:3px;--dm-dg:1px}
.dm-ths-dg .dm-r{animation:dm-thsor 1.6s linear infinite}
.dm-ths-dg .dm-c{opacity:.85;animation:dm-thscore 1.6s var(--dm-ease-io) infinite}
@keyframes dm-thsor{0%{opacity:1}30%{opacity:.45}60%,100%{opacity:.14}}
@keyframes dm-thscore{50%{transform:scale(.7)}}
/* Scan: three lines of text in dots, a column of light sweeping across them */
.dm-ths-dg[data-k="scan"]{--dm-n:6;--dm-ds:2px;--dm-dg:1px}
.dm-ths-dg .dm-l{animation:dm-thsscl 1.6s linear infinite}
.dm-ths-dg .dm-b{opacity:.06;animation:dm-thsscb 1.6s linear infinite}
@keyframes dm-thsscl{0%{opacity:1}35%,100%{opacity:.3}}
@keyframes dm-thsscb{0%{opacity:.38}25%,100%{opacity:.06}}
/* Morph: the dots draw a rectangle, then a circle, then a triangle, and back; between shapes every dot flickers like
   Matrix's, each a little out of step (its own small delay), before it settles into the next shape (owner, 5 Nov) */
.dm-ths-dg[data-k="morph"]{--dm-n:7;--dm-ds:2px;--dm-dg:1px}
.dm-ths-dg[data-k="morph"] i{animation-duration:3.2s;animation-timing-function:var(--dm-ease-io);animation-iteration-count:infinite}
.dm-ths-dg .dm-m0{animation-name:dm-thsm0}.dm-ths-dg .dm-m1{animation-name:dm-thsm1}.dm-ths-dg .dm-m2{animation-name:dm-thsm2}.dm-ths-dg .dm-m3{animation-name:dm-thsm3}.dm-ths-dg .dm-m4{animation-name:dm-thsm4}.dm-ths-dg .dm-m5{animation-name:dm-thsm5}.dm-ths-dg .dm-m6{animation-name:dm-thsm6}.dm-ths-dg .dm-m7{animation-name:dm-thsm7}
@keyframes dm-thsm0{0%{opacity:.12}20%{opacity:.12}22.6%{opacity:.5}25.2%{opacity:.12}27.8%{opacity:.4}30.4%{opacity:.12}33%{opacity:.12}53%{opacity:.12}55.6%{opacity:.5}58.2%{opacity:.12}60.8%{opacity:.4}63.4%{opacity:.12}66%{opacity:.12}86%{opacity:.12}88.8%{opacity:.5}91.6%{opacity:.12}94.4%{opacity:.4}97.2%{opacity:.12}100%{opacity:.12}}
@keyframes dm-thsm1{0%{opacity:1}20%{opacity:1}22.6%{opacity:.85}25.2%{opacity:.2}27.8%{opacity:.95}30.4%{opacity:.3}33%{opacity:.12}53%{opacity:.12}55.6%{opacity:.5}58.2%{opacity:.12}60.8%{opacity:.4}63.4%{opacity:.12}66%{opacity:.12}86%{opacity:.12}88.8%{opacity:.85}91.6%{opacity:.2}94.4%{opacity:.95}97.2%{opacity:.3}100%{opacity:1}}
@keyframes dm-thsm2{0%{opacity:.12}20%{opacity:.12}22.6%{opacity:.85}25.2%{opacity:.2}27.8%{opacity:.95}30.4%{opacity:.3}33%{opacity:1}53%{opacity:1}55.6%{opacity:.85}58.2%{opacity:.2}60.8%{opacity:.95}63.4%{opacity:.3}66%{opacity:.12}86%{opacity:.12}88.8%{opacity:.5}91.6%{opacity:.12}94.4%{opacity:.4}97.2%{opacity:.12}100%{opacity:.12}}
@keyframes dm-thsm3{0%{opacity:1}20%{opacity:1}22.6%{opacity:.85}25.2%{opacity:.2}27.8%{opacity:.95}30.4%{opacity:.3}33%{opacity:1}53%{opacity:1}55.6%{opacity:.85}58.2%{opacity:.2}60.8%{opacity:.95}63.4%{opacity:.3}66%{opacity:.12}86%{opacity:.12}88.8%{opacity:.85}91.6%{opacity:.2}94.4%{opacity:.95}97.2%{opacity:.3}100%{opacity:1}}
@keyframes dm-thsm4{0%{opacity:.12}20%{opacity:.12}22.6%{opacity:.5}25.2%{opacity:.12}27.8%{opacity:.4}30.4%{opacity:.12}33%{opacity:.12}53%{opacity:.12}55.6%{opacity:.85}58.2%{opacity:.2}60.8%{opacity:.95}63.4%{opacity:.3}66%{opacity:1}86%{opacity:1}88.8%{opacity:.85}91.6%{opacity:.2}94.4%{opacity:.95}97.2%{opacity:.3}100%{opacity:.12}}
@keyframes dm-thsm5{0%{opacity:1}20%{opacity:1}22.6%{opacity:.85}25.2%{opacity:.2}27.8%{opacity:.95}30.4%{opacity:.3}33%{opacity:.12}53%{opacity:.12}55.6%{opacity:.85}58.2%{opacity:.2}60.8%{opacity:.95}63.4%{opacity:.3}66%{opacity:1}86%{opacity:1}88.8%{opacity:.85}91.6%{opacity:.2}94.4%{opacity:.95}97.2%{opacity:.3}100%{opacity:1}}
@keyframes dm-thsm6{0%{opacity:.12}20%{opacity:.12}22.6%{opacity:.85}25.2%{opacity:.2}27.8%{opacity:.95}30.4%{opacity:.3}33%{opacity:1}53%{opacity:1}55.6%{opacity:.85}58.2%{opacity:.2}60.8%{opacity:.95}63.4%{opacity:.3}66%{opacity:1}86%{opacity:1}88.8%{opacity:.85}91.6%{opacity:.2}94.4%{opacity:.95}97.2%{opacity:.3}100%{opacity:.12}}
@keyframes dm-thsm7{0%{opacity:1}20%{opacity:1}22.6%{opacity:.85}25.2%{opacity:.2}27.8%{opacity:.95}30.4%{opacity:.3}33%{opacity:1}53%{opacity:1}55.6%{opacity:.85}58.2%{opacity:.2}60.8%{opacity:.95}63.4%{opacity:.3}66%{opacity:1}86%{opacity:1}88.8%{opacity:.85}91.6%{opacity:.2}94.4%{opacity:.95}97.2%{opacity:.3}100%{opacity:1}}
/* Stream: three lines of four dots, the same size as Matrix (18 by 18: 3px dots, 2px apart across) (owner, 5 Nov); they light
   up one by one, line by line, hold, then all fade out together. Each dot's moment is its own keyframe (thss0 to thss11) */
.dm-ths-dg[data-k="stream"]{--dm-n:4;--dm-ds:3px;--dm-dg:2px;row-gap:4px;height:18px;align-content:start;padding-top:1px;box-sizing:border-box}
.dm-ths-dg[data-k="stream"] i{animation-duration:2.2s;animation-timing-function:linear;animation-iteration-count:infinite}
.dm-ths-dg .dm-s0{animation-name:dm-thss0}.dm-ths-dg .dm-s1{animation-name:dm-thss1}.dm-ths-dg .dm-s2{animation-name:dm-thss2}.dm-ths-dg .dm-s3{animation-name:dm-thss3}.dm-ths-dg .dm-s4{animation-name:dm-thss4}.dm-ths-dg .dm-s5{animation-name:dm-thss5}.dm-ths-dg .dm-s6{animation-name:dm-thss6}.dm-ths-dg .dm-s7{animation-name:dm-thss7}.dm-ths-dg .dm-s8{animation-name:dm-thss8}.dm-ths-dg .dm-s9{animation-name:dm-thss9}.dm-ths-dg .dm-s10{animation-name:dm-thss10}.dm-ths-dg .dm-s11{animation-name:dm-thss11}
@keyframes dm-thss0{0%,4.0%{opacity:.14}7.5%,82%{opacity:1}94%,100%{opacity:.14}}
@keyframes dm-thss1{0%,9.5%{opacity:.14}13.0%,82%{opacity:1}94%,100%{opacity:.14}}
@keyframes dm-thss2{0%,15.0%{opacity:.14}18.5%,82%{opacity:1}94%,100%{opacity:.14}}
@keyframes dm-thss3{0%,20.5%{opacity:.14}24.0%,82%{opacity:1}94%,100%{opacity:.14}}
@keyframes dm-thss4{0%,26.0%{opacity:.14}29.5%,82%{opacity:1}94%,100%{opacity:.14}}
@keyframes dm-thss5{0%,31.5%{opacity:.14}35.0%,82%{opacity:1}94%,100%{opacity:.14}}
@keyframes dm-thss6{0%,37.0%{opacity:.14}40.5%,82%{opacity:1}94%,100%{opacity:.14}}
@keyframes dm-thss7{0%,42.5%{opacity:.14}46.0%,82%{opacity:1}94%,100%{opacity:.14}}
@keyframes dm-thss8{0%,48.0%{opacity:.14}51.5%,82%{opacity:1}94%,100%{opacity:.14}}
@keyframes dm-thss9{0%,53.5%{opacity:.14}57.0%,82%{opacity:1}94%,100%{opacity:.14}}
