/* Matrix: each dot keeps its own beat, so the grid twinkles instead of sweeping */
.dm-ths-mtx{display:grid;grid-template-columns:repeat(4,3px);gap:2px}
.dm-ths-mtx i{display:block;width:3px;height:3px;border-radius:50%;background:currentColor;opacity:.2;animation:dm-thstw 2s var(--dm-ease-io) infinite}
.dm-ths-mtx i:nth-child(3n){animation-duration:2.6s}.dm-ths-mtx i:nth-child(3n+1){animation-duration:1.7s}
.dm-ths-mtx i:nth-child(1){animation-delay:-.1s}.dm-ths-mtx i:nth-child(2){animation-delay:-.9s}.dm-ths-mtx i:nth-child(3){animation-delay:-1.9s}.dm-ths-mtx i:nth-child(4){animation-delay:-.4s}
.dm-ths-mtx i:nth-child(5){animation-delay:-1.2s}.dm-ths-mtx i:nth-child(6){animation-delay:-.2s}.dm-ths-mtx i:nth-child(7){animation-delay:-1.6s}.dm-ths-mtx i:nth-child(8){animation-delay:-.7s}
.dm-ths-mtx i:nth-child(9){animation-delay:-.5s}.dm-ths-mtx i:nth-child(10){animation-delay:-1.4s}.dm-ths-mtx i:nth-child(11){animation-delay:-.05s}.dm-ths-mtx i:nth-child(12){animation-delay:-1s}
.dm-ths-mtx i:nth-child(13){animation-delay:-2.1s}.dm-ths-mtx i:nth-child(14){animation-delay:-.8s}.dm-ths-mtx i:nth-child(15){animation-delay:-1.3s}.dm-ths-mtx i:nth-child(16){animation-delay:-.3s}
@keyframes dm-thstw{0%,100%{opacity:.2}45%,60%{opacity:1}}
/* Stack: three pages; the front one leaves and the others move up, each a third of the loop behind the next */
.dm-ths-stk{position:relative;width:20px;height:20px}
.dm-ths-stk i{position:absolute;left:3px;top:3px;width:11px;height:13px;border-radius:calc(2.5px * var(--dm-rk));background:var(--dm-surface);box-shadow:inset 0 0 0 1.25px currentColor;color:color-mix(in srgb,var(--dm-fg) 34%,transparent);animation:dm-thsstk 2.4s var(--dm-ease-io) infinite}
.dm-ths-stk i:nth-child(1){translate:6px -3px;opacity:.6;z-index:1}
.dm-ths-stk i:nth-child(2){translate:3px 0;opacity:.85;z-index:2;animation-delay:-.8s}
.dm-ths-stk i:nth-child(3){translate:0 3px;z-index:3;color:var(--dm-accent-mark,var(--dm-accent));animation-delay:-1.6s}
@keyframes dm-thsstk{0%{translate:6px -3px;opacity:.6;z-index:1;color:color-mix(in srgb,var(--dm-fg) 34%,transparent)}25%{translate:3px 0;opacity:.85;z-index:2;color:color-mix(in srgb,var(--dm-fg) 34%,transparent)}50%,66%{translate:0 3px;opacity:1;z-index:3;color:var(--dm-accent-mark,var(--dm-accent))}80%{translate:-5px 6px;opacity:0;z-index:3;color:var(--dm-accent-mark,var(--dm-accent))}81%{translate:6px -3px;opacity:0;z-index:1;color:color-mix(in srgb,var(--dm-fg) 34%,transparent)}100%{translate:6px -3px;opacity:.6;z-index:1;color:color-mix(in srgb,var(--dm-fg) 34%,transparent)}}
/* six choices fit under the demo on a phone */
@container (max-width:380px){.dm-ths-dm>.dm-demo .dm-seg2 button{padding:0 7px;font-size:12px}}
/* reduced motion: every mark holds a pose that still reads (the orbit's light and tail, a circle, a lit column, the first
   words, a lit diamond, a stack), the caret stays lit and the sweep goes */
@media (prefers-reduced-motion:reduce){.dm-ths-mk *,.dm-ths-car{animation:none!important}.dm-ths-dg .dm-p{opacity:1}.dm-ths-mtx i:is(:nth-child(2),:nth-child(5),:nth-child(7),:nth-child(10),:nth-child(12),:nth-child(15)){opacity:1}}
/* Blueprint: a square tile with a hairline, square dots, marks that tick in steps and a block caret */
:root:not([data-style="soft"]) .dm-ths-mk:not(:where([data-style="soft"],[data-style="soft"] *)){background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent)}
:root:not([data-style="soft"]) .dm-ths-dg i:not(:where([data-style="soft"],[data-style="soft"] *)){border-radius:0}
:root:not([data-style="soft"]) .dm-ths-car:not(:where([data-style="soft"],[data-style="soft"] *)){width:7px;vertical-align:-3px}
:root:not([data-style="soft"]) .dm-ths-mtx i:not(:where([data-style="soft"],[data-style="soft"] *)){animation-timing-function:steps(1,end)}
:root:not([data-style="soft"]) .dm-ths-stk i:not(:where([data-style="soft"],[data-style="soft"] *)){animation-timing-function:steps(3)}
